import { describe, it, expect } from "vitest";
import { calculatePremium, calculateClaim } from "./policy.js";

describe("Premium calculation", () => {
  // Simplest cases
  it.todo("empty item list → premium 5 G (only the processing fee)");

  // Base premiums per item type (single item, no modifiers, newcomer)
  it.todo("single sword, no modifiers → base premium 100 G (before first-insurance surcharge and fee)");
  it.todo("single amulet, no modifiers → base premium 60 G (before first-insurance surcharge and fee)");
  it.todo("single staff, no modifiers → base premium 80 G (before first-insurance surcharge and fee)");
  it.todo("single potion, no modifiers → base premium 40 G (before first-insurance surcharge and fee)");
  it.todo("single rune, no modifiers → base premium 25 G (before first-insurance surcharge and fee)");
  it.todo("single moonstone, no modifiers → base premium 25 G (before first-insurance surcharge and fee)");

  // Component block discount (3-alike)
  it.todo("2 runes → base premium 50 G (no block)");
  it.todo("3 runes → base premium 60 G (block applies)");
  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
  it.todo("7 runes → base premium 175 G");
  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");

  // Item-specific modifiers in isolation
  it.todo("cursed sword → 50% curse surcharge added to sword's base premium (100 G → 150 G before other modifiers)");
  it.todo("sword with enchantment exactly 5 → 30% high-enchantment surcharge applies (100 G → 130 G before other modifiers)");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge (stays 100 G base)");
  it.todo("cursed sword with enchantment exactly 5 → both curse and high-enchantment surcharges apply (100 G → 180 G before other modifiers)");

  // Policy-wide modifiers in isolation
  it.todo("customer with exactly 2 years with MHPCO → 20% loyalty discount applies to policy base premium");
  it.todo("customer's first quote (no previous contracts) → 10% first-insurance surcharge applies to policy base premium");
  it.todo("customer's second quote in the scenario → 15% follow-up discount applies to policy base premium");
  it.todo("processing fee of 5 G is added to every premium");

  // Modifier scope on multi-item policies
  it.todo(
    "policy with cursed sword (100 G base) and plain amulet (60 G base) → policy base premium 160 G; curse surcharge adds 50 G (50% of cursed sword's base premium, not policy total) → 210 G before further modifiers and fee",
  );

  // Rounding
  it.todo("premium calculation yielding 197.5 G → final premium rounds up to 198 G");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // Integration examples (full end-to-end premium)
  it.todo(
    "newcomer with cursed sword (steel, enchantment 3): 100 base + 50 curse + 10 first-insurance = 160, +5 fee = 165 G",
  );
  it.todo(
    "long-standing customer's (3 years) second contract with cursed sword (steel, enchantment 7): 100 base + 50 curse + 30 high-enchantment − 20 loyalty + 10 first-insurance (still applies per-item) − 15 follow-up = 155, +5 fee = 160 G",
  );
});

describe("Claim/payout calculation", () => {
  // Simplest / standard cases
  it.todo(
    "regular sword (steel, enchantment 3), damage 500 G → payout 400 G (full reimbursement minus 100 G deductible; no special clause)",
  );
  it.todo(
    "damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (full reimbursement minus 100 G deductible; no enchantment/material clause applies)",
  );

  // Modifier thresholds for claim clauses
  it.todo(
    "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment 50% clause applies, then deductible)",
  );
  it.todo(
    "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (both clauses apply; 50% rule wins over full reimbursement, then deductible: 500 − 100)",
  );
  it.todo(
    "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (only dragon-material clause applies: full reimbursement, then deductible: 800 − 100)",
  );
  it.todo(
    "steel sword, enchantment 9, damage 1000 G → payout 400 G (only high-enchantment clause applies: 50% first, then deductible: 500 − 100)",
  );

  // Deductible per damage event
  it.todo(
    "dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (100 G deductible applies once per damaged item)",
  );

  // Multiple items of the same type
  it.todo("policy covers two swords → insurance sum 2000 G (= 2×1000), cap 4000 G");
  it.todo(
    "dragon attack damages both swords; damages array has two {itemType: 'sword', ...} entries → each entry treated as a separate damage with its own deductible",
  );

  // Cap exhaustion and insurance sum computation
  it.todo("policy covers a sword and an amulet → insurance sum 1600 G (1000 + 600), cap 3200 G");
  it.todo(
    "cursed sword (insurance value 1000 G, premium with modifiers 165 G) → cap 2000 G (based on unmodified insurance value; premium modifiers do not raise the cap)",
  );
  it.todo(
    "policy covers a sword and 3 runes (a block) → insurance sum 1750 G (1000 + 3×250); block discount affects premium only, not insurance sum",
  );
  it.todo(
    "sword insured (insurance sum 1000 G, cap 2000 G); first of two successive 1500 G claims → payout 1400 G, cap remaining 600 G",
  );
  it.todo(
    "sword insured (insurance sum 1000 G, cap 2000 G); second successive 1500 G claim after first → payout 600 G, cap remaining 0 G (desired 1400 G reduced to remaining cap)",
  );

  // Rounding
  it.todo("payout calculation yielding 350.5 G → final payout rounds down to 350 G");
});

