export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;

// Main items and components share one lookup: today every item type is priced
// the same way (single base premium, summed). Split this only when behavior
// actually diverges (e.g. component block-discount rules).
const BASE_PREMIUMS: Record<string, number> = {
  // main items
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  // components
  rune: 25,
  moonstone: 25,
};

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const FIRST_INSURANCE_SURCHARGE = 0.1;

// Guards against float drift (e.g. 100 * 1.1 === 110.00000000000001) before
// rounding up to the nearest whole gold piece, as the spec requires exact-G amounts.
const roundUpToGold = (amount: number): number => Math.ceil(Math.round(amount * 100) / 100);

// A block discount replaces the per-unit price with one flat premium, but only
// when a type's count exactly matches the block size (e.g. 3 runes → 60G flat;
// 2 or 4 runes still price per-unit).
const premiumForType = (type: string, count: number): number =>
  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * BASE_PREMIUMS[type];

export const calculatePremium = (customer: Customer, items: Item[]): number => {
  if (items.length === 0) return PROCESSING_FEE;

  const countsByType: Record<string, number> = {};
  for (const item of items) {
    countsByType[item.type] = (countsByType[item.type] ?? 0) + 1;
  }

  const policyBase = Object.entries(countsByType).reduce(
    (sum, [type, count]) => sum + premiumForType(type, count),
    0,
  );
  const withSurcharge = policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
  return roundUpToGold(withSurcharge) + PROCESSING_FEE;
};
```

