        { type: "rune" },
        { type: "rune" },
        { type: "moonstone" },
        { type: "moonstone" },
        { type: "moonstone" },
      ]),
    ).toBe(137);
  });

  // Item-specific modifiers in isolation
  it("cursed sword → 50% curse surcharge added to sword's base premium (100 G → 150 G before other modifiers)", () => {
    expect(calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }])).toBe(170);
  });
  it("sword with enchantment exactly 5 → 30% high-enchantment surcharge applies (100 G → 130 G before other modifiers)", () => {
    expect(calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5 }])).toBe(148);
  });
  it("sword with enchantment 4 → no high-enchantment surcharge (stays 100 G base)", () => {
    expect(calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 4 }])).toBe(115);
  });
  it("cursed sword with enchantment exactly 5 → both curse and high-enchantment surcharges apply (100 G → 180 G before other modifiers)", () => {
    expect(
      calculatePremium({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true, enchantment: 5 }]),
    ).toBe(203);
  });

  // Policy-wide modifiers in isolation
  it.todo("customer with exactly 2 years with MHPCO → 20% loyalty discount applies to policy base premium");
  it.todo("customer's first quote (no previous contracts) → 10% first-insurance surcharge applies to policy base premium");
  it.todo("customer's second quote in the scenario → 15% follow-up discount applies to policy base premium");
  it.todo("processing fee of 5 G is added to every premium");

  // Modifier scope on multi-item policies
  it.todo(
    "policy with cursed sword (100 G base) and plain amulet (60 G base) → policy base premium 160 G; curse surcharge adds 50 G (50% of cursed sword's base premium, not policy total) → 210 G before further modifiers and fee",
  );

  // Rounding
  it.todo("premium calculation yielding 197.5 G → final premium rounds up to 198 G");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // Integration examples (full end-to-end premium)
