import { calculatePremium, processClaim, type Item } from "./policy.js";

export interface CliResult {
  stdout: string;
  stderr: string;
  exitCode: number;
}

export const runCli = (input: string): CliResult => {
  const scenario = JSON.parse(input);
  const results: unknown[] = [];
  const policyItems: Item[][] = [];
  const policyQuoteCount: number[] = [];
  const policyPayoutTotal: number[] = [];

  scenario.steps.forEach((step: any, index: number) => {
    if (step.op === "quote") {
      const previousQuoteCount = policyQuoteCount[index] ?? 0;
      const premium = calculatePremium(scenario.customer, step.items, previousQuoteCount);
      policyItems[index] = step.items;
      policyQuoteCount[index] = previousQuoteCount + 1;
      policyPayoutTotal[index] = 0;
      results.push({ premium });
    } else if (step.op === "claim") {
      const items = policyItems[step.policy];
      const previousPayoutTotal = policyPayoutTotal[step.policy];
      const claimResult = processClaim(items, step.incident.damages, previousPayoutTotal);
      policyPayoutTotal[step.policy] += claimResult.payout;
      results.push(claimResult);
    }
  });

  return { stdout: JSON.stringify({ results }), stderr: "", exitCode: 0 };
};

