const CAP_MULTIPLIER = 2;

export const processClaim = (items: Item[], damages: Damage[], previousPayoutTotal = 0): ClaimResult => {
  const uncappedPayout = damages.reduce((sum, damage) => {
    // The non-null assertion assumes every damage references an item present
    // on the policy — true for all cases tested so far. Once a test covers a
    // damage referencing an item not in the policy, this needs real error
    // handling (or a filtered/validated lookup) instead of the assertion.
